{
  "itemTaxonomy": [
    {
      "category": "Beauty",
      "description": "Beauty",
      "productTypeGroup": [
        {
          "productTypeGroupName": "Fragrances",
          "description": "Fragrance",
          "productType": [
            {
              "productTypeName": "Body Sprays",
              "description": "Body spray is a perfume or cologne product, similar to aerosol deodorant, which is intended to be used elsewhere on the body besides the armpits. Body sprays are lighter in strength than cologne, generally less expensive, and double as deodorant a body spray is just a milder form of perfume. Body spray is a mixture of water and alcohol along with various extracts.  Body Sprays will also often be called Body Mists or Hair Mists.  The Body Sprays product type includes Body Spray bundles, multi sets, and gift sets, as long as they don't contain perfume or cologne."
            },
            {
              "productTypeName": "Fragrance Sets",
              "description": "Fragrance Sets are perfumes and colognes in a bigger box packaging than an individual perfume or cologne item. These items will have more than 1 product inside its packaging. Fragrance Sets are often meant to be given as gifts or used to sample a variety of fragrances. Fragrance Sets sometimes have see-through plastic windows on the packaging that allow the consumer to view the items in the set. Fragrance Sets can be made up of all perfume items, all cologne items, or a mix of perfume/cologne items and lotions, skin care, makeup, or other beauty products, etc.  If the item doesn't contain a perfume or cologne, it is not considered a Fragrance Set.  Body Spray sets are not Fragrance Sets.\n\nIf a listing has bulk/bundles identical items (2 or more of the same exact item, for example 3 boxes of the identical perfume), it is not a fragrance set."
            },
            {
              "productTypeName": "Perfumes",
              "description": "Fragrant liquids typically made from essential oils extracted from flowers and spices, used to impart a pleasant smell to one's body or clothes. Perfumes and colognes come in a wide array of containers: Mini & Travel, Rollerball, Full Size, and Value Size. Perfumes and colognes can use application techniques including: dabbing, spraying, spritzing, rolling-on, etc. Perfumes and colognes are sometimes differentiated by gender: Perfumes are for women and colognes are for men. There are colognes/perfumes that are unisex, as well. Perfumes and Colognes can also be identified by their Chemical Composition. Perfumes and Colognes are NOT body sprays.  Perfumes and Colognes were recently separated into two individual SOPs.  Any way they come in (Perfumes & Colognes, Perfumes, Colognes is acceptable.  To be under Perfumes, gender = female.  To be under Colognes, gender = male."
            },
            {
              "productTypeName": "Colognes",
              "description": "Fragrant liquids typically made from essential oils extracted from flowers and spices, used to impart a pleasant smell to one's body or clothes. Perfumes and colognes come in a wide array of containers: Mini & Travel, Rollerball, Full Size, and Value Size. Perfumes and colognes can use application techniques including: dabbing, spraying, spritzing, rolling-on, etc. Perfumes and colognes are sometimes differentiated by gender: Perfumes are for women and colognes are for men. There are colognes/perfumes that are unisex, as well. Perfumes and Colognes can also be identified by their Chemical Composition. Perfumes and Colognes are NOT body sprays.  Perfumes and Colognes were recently separated into two individual SOPs.  Any way they come in (Perfumes & Colognes, Perfumes, Colognes is acceptable.  To be under Perfumes, gender = female.  To be under Colognes, gender = male."
            }
          ],
          "department": [
            {
              "departmentName": "BEAUTY",
              "departmentNumber": "46"
            }
          ]
        },
        {
          "productTypeGroupName": "Skin Care",
          "description": "Skin Care",
          "productType": [
            {
              "productTypeName": "Acne Creams",
              "description": "Acne products usually contain the active ingredient salicylic acid or benzoyl peroxide. These substances reduce the amount of oil your body produces. They also fight inflammation. These effects help treat existing blemishes and prevent new ones from forming.  This includes acne cream, spot treatment, pads and patches."
            },
            {
              "productTypeName": "Acne Treatment Systems",
              "description": "Acne products usually contain the active ingredient salicylic acid or benzoyl peroxide. These substances reduce the amount of oil your body produces. They also fight inflammation. These effects help treat existing blemishes and prevent new ones from forming.  This Product Type includes systems that usually have multiple steps and multiple products (ex, a cleanser, moisturizer and spot treatment)."
            },
            {
              "productTypeName": "Exfoliants & Scrubs",
              "description": "Exfoliants are used to get rid of dry skin and include things like micro-bead facial scrubs, crushed apricot kernel or almond shells, sugar or salt crystals."
            },
            {
              "productTypeName": "Eye Creams & Serums",
              "description": "Eye serums are highly-concentrated, lightweight formulations that help deliver active ingredients to help target concerns like crow's feet, puffiness and dark circles. Eye serums can be used alone or applied under an eye cream.  Does not include Eye Masks."
            },
            {
              "productTypeName": "Eye Masks",
              "description": "Eye masks typically look like comma-shaped patches and are infused with lightweight but potent serums packed with innovative ingredients like retinol, hyaluronic acid and ceramides designed to plump your skin and bust dark circles.  Does not include Eye Creams & Serums, Sleep Masks (without product in them), Costume Masks."
            },
            {
              "productTypeName": "Face Serums",
              "description": "Serum is a skincare product you can apply to your skin after cleansing but before moisturizing with the intent of delivering powerful ingredients directly into the skin."
            },
            {
              "productTypeName": "Facial Cleansers",
              "description": "Cleanser is a facial care product that is used to remove dead skin cells, oil, dirt, and other types of pollutants from the skin of the face. This helps to unclog pores and prevent skin conditions such as acne.  Does not include Exfoliators, Makeup Removers, Face Wipes, Toners, Blotting Papers, Acne Products"
            },
            {
              "productTypeName": "Facial Masks",
              "description": "Facial masks generally stay on your skin for 10 to 15 minutes and contain ingredients like clay, black moor mud, aloe vera, seaweed, algae, essential oils, massage oils, herbs, and vitamins.  They can be a product you apply to your skin or a sheet mask."
            },
            {
              "productTypeName": "Facial Moisturizers",
              "description": "Moisturizer is put on skin to increase moisture levels and can also protect against sun.  Includes Night Creams, Face Oils, Face Mists, Neck & Decollete Creams.  Does not include Tinted Moisturizer, BB Cream, CC Cream, Self Tanners."
            },
            {
              "productTypeName": "Facial Toners & Astringents",
              "description": "Astringent and toner are both water-based and are put on the face to remove skin residue and tighten pores, to be used after washing and before moisturizing the skin. Toners do not contain alcohol, so toners are milder and less irritating to the skin. "
            },
            {
              "productTypeName": "Facial Treatments",
              "description": "A skincare product you can apply to your skin with the intent of delivering powerful ingredients directly into the skin.  A common treatment would be a Facial Peel.  Does not include Face Serums, Acne Treatments."
            },
            {
              "productTypeName": "Facial Wipes",
              "description": "Face wipes provide you with a quick and easy alternative to your regular facial cleansing routine. They allow you to remove makeup and oil from your skin without using water or cleansers.  They include Blotting Papers and Wipes that remove makeup."
            },
            {
              "productTypeName": "Makeup Removers",
              "description": "Cleansing oils, balms, micellar waters that claim to remove waterproof mascara and other makeup with just water.  Does not include Wipes that remove makeup."
            },
            {
              "productTypeName": "Skin Care Sets",
              "description": "These contain multiple skin care items.  They can be multiple items from the same brand, or collection, they can be sampler sets or gift sets.  Does not include Acne Treatment Systems."
            },
            {
              "productTypeName": "Skin Lighteners",
              "description": "Skin whitening, also known as skin lightening and skin bleaching, refers to the practice of using chemical substances in an attempt to lighten the skin or provide an even skin color by reducing the melanin concentration in the skin.  Does not include Face Serums that remove dark spots.  This may be a product that can be used on the face or body."
            }
          ],
          "department": [
            {
              "departmentName": "BEAUTY",
              "departmentNumber": "46"
            },
            {
              "departmentName": "IMPULSE MERCHANDISE",
