        {
          "productTypeGroupName": "Hair Care",
          "description": "Hair Care",
          "productType": [
            {
              "productTypeName": "3-in-1 Shampoo, Conditioner & Body Washes",
              "description": "One container that is a combination of shampoo, conditioner and body wash.  Typically for men or for women or for kids specifically.\n"
            },
            {
              "productTypeName": "Conditioners",
              "description": "Hair conditioner is a hair care product used to improve the feel, appearance and manageability of hair. Its main purpose is to reduce friction between strands of hair to allow smoother brushing or combing, which might otherwise cause damage to the scalp."
            },
            {
              "productTypeName": "Conditioning Shampoos",
              "description": "A shampoo and conditioner in one.\n"
            },
            {
              "productTypeName": "Shampoo & Conditioner Sets",
              "description": "A set that includes both a conditioner and a shampoo, both in separate containers. "
            },
            {
              "productTypeName": "Shampoos",
              "description": "A hair care product, typically in the form of a viscous liquid, that is used for cleaning hair. Less commonly, shampoo is available in bar form, like a bar of soap. Shampoo is used by applying it to wet hair, massaging the product into the scalp, and then rinsing it out."
            },
            {
              "productTypeName": "Dry Shampoos",
              "description": "Dry shampoo is a type of shampoo which reduces hair greasiness without the need for water. It is in powder form and is typically administered from an aerosol can"
            },
            {
              "productTypeName": "Hair & Scalp Treatments",
              "description": "Scalp treatments are used to unclog the hair follicles, releasing natural conditioning oils. Plus, they stimulate blood flow, so nutrients can better reach the scalp and nourish your hair.  These can be scrubs or something you put directly on the scalp.\n"
            },
            {
              "productTypeName": "Hair Loss Treatments",
              "description": "Hair loss treatments are products that stimulate hair growth and prevent hair loss.  They can either be something applied to the head or in a pill form.  They include a active ingredient such as Minoxidil (Rogaine).\n"
            },
            {
              "productTypeName": "Hair Masks",
              "description": "A hair mask is a deep conditioning treatment that helps to heal damaged hair. They contain rich ingredients such as natural oils and lipids, in heavier concentrations than normal conditioners. You leave a hair mask in for an extended period of time, three minutes to overnight.\n"
            },
            {
              "productTypeName": "Hair Oils",
              "description": "Hair oil is oil applied to the hair as a cosmetic, conditioner, styling aid, restorative or tonic. \n"
            },
            {
              "productTypeName": "Hair Pomades",
              "description": "Pomade is a greasy, waxy, or a water-based substance that is used to style hair. Pomade generally gives the user's hair a shiny and slick appearance."
            },
            {
              "productTypeName": "Hair Styling Waxes",
              "description": "Hair wax is a thick hairstyling product containing wax, used to assist with holding the hair. In contrast with hair gel, most of which contain alcohol, hair wax remains pliable and has less chance of drying out.\n"
            },
            {
              "productTypeName": "Hair Styling Creams",
              "description": "Hair cream is a soft and light substance that doesn't feel greasy or stiff when applied to hair. Cream controls static and frizziness while adding a natural shine to your head of locks. Hair creams often include moisturizing ingredients such as olive oil or silk amino acids, which help conditions hair strands.\n"
            },
            {
              "productTypeName": "Hair Styling Gels",
              "description": "Hair gel is a hairstyling product that is used to harden hair into a particular hairstyle. "
            },
            {
              "productTypeName": "Hair Styling Mousses",
              "description": "Hair mousse adds volume to hair and often provides both conditioning and hold, without any clumps or build-up. It is a hairstyling product which works by using synthetic resins to coat the hairs, to assist the hair in taking a certain shape.\n"
            },
            {
              "productTypeName": "Hair Sprays",
              "description": "Hair spray is a common cosmetic hairstyling product that is sprayed onto hair to protect against humidity and wind. Hair sprays typically consist of several components for the hair as well as a propellant.\n"
            },
            {
              "productTypeName": "Hair Serums",
              "description": "A hair serum is a silicone-based product that coats the surface of your hair. Unlike hair oil, it does not penetrate the hair cuticles or cause changes to the hair structure. Instead, it enhances the curliness and smoothness of hair.\n"
            }
          ],
